"use client";

import { motion } from "motion/react";
import type { Dictionary } from "@/content";
import { usMap } from "@/content/us-map";
import { Reveal } from "../Reveal";
import { SectionHeading } from "./ui";

// Lower-48 dot map (public/apg/us-dots.svg, generated by scripts/make-us-map.mjs) with amber routes that draw
// out from Nashville one after another when the section scrolls into view.
// Idea from the "World Map" component on 21st.dev (Aceternity UI, MIT), rebuilt for the US and the site's style.

const { width: W, height: H, hub, cities } = usMap;
const ease = [0.22, 1, 0.36, 1] as const;
const STAGGER = 0.12;
const DRAW = 1.1;

// A curved route that bows upward, more for longer routes
function route(to: { x: number; y: number }) {
  const mx = (hub.x + to.x) / 2;
  const my = (hub.y + to.y) / 2;
  const lift = Math.hypot(to.x - hub.x, to.y - hub.y) * 0.32;
  return `M${hub.x} ${hub.y} Q${mx} ${my - lift} ${to.x} ${to.y}`;
}

export function CoverageMap({ t: coverage }: { t: Dictionary["coverage"] }) {
  return (
    <section className="overflow-hidden bg-[linear-gradient(160deg,#061232_0%,#0b2463_80%)] py-16 lg:py-[110px]">
      <div className="container-apg">
        <Reveal>
          <SectionHeading tone="dark" align="center" title={coverage.title} lead={coverage.lead} titleClassName="lg:max-w-[760px]" />
        </Reveal>

        <motion.div
          className="relative mx-auto mt-10 w-full max-w-[1040px] lg:mt-16"
          style={{ aspectRatio: `${W} / ${H}` }}
          initial="hidden"
          whileInView="shown"
          viewport={{ once: true, margin: "0px 0px -120px 0px" }}
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/apg/us-dots.svg" alt="" aria-hidden="true" className="absolute inset-0 size-full opacity-80" />

          <svg viewBox={`0 0 ${W} ${H}`} className="absolute inset-0 size-full overflow-visible" aria-hidden="true">
            <defs>
              {cities.map((c, i) => (
                <linearGradient key={c.name} id={`route-${i}`} gradientUnits="userSpaceOnUse" x1={hub.x} y1={hub.y} x2={c.x} y2={c.y}>
                  <stop offset="0" stopColor="#f5a524" />
                  <stop offset="1" stopColor="#f5a524" stopOpacity="0.35" />
                </linearGradient>
              ))}
            </defs>

            {cities.map((c, i) => (
              <g key={c.name}>
                <motion.path
                  d={route(c)}
                  fill="none"
                  stroke={`url(#route-${i})`}
                  strokeLinecap="round"
                  // width in map units (no vector-effect: it breaks the line-drawing animation, routes came out dashed)
                  className="[stroke-width:0.32] lg:[stroke-width:0.16]"
                  variants={{
                    hidden: { pathLength: 0, opacity: 0 },
                    shown: { pathLength: 1, opacity: 1, transition: { duration: DRAW, ease, delay: 0.3 + i * STAGGER } },
                  }}
                />
                <motion.circle
                  cx={c.x}
                  cy={c.y}
                  r={0.45}
                  fill="#f5a524"
                  variants={{
                    hidden: { opacity: 0, scale: 0 },
                    shown: { opacity: 1, scale: 1, transition: { duration: 0.4, ease, delay: 0.3 + i * STAGGER + DRAW * 0.85 } },
                  }}
                />
              </g>
            ))}

            {/* Nashville: a ring that keeps pulsing outward, and the hub dot */}
            <motion.circle
              cx={hub.x}
              cy={hub.y}
              r={0.9}
              fill="none"
              stroke="#f5a524"
              strokeWidth={1.2}
              vectorEffect="non-scaling-stroke"
              variants={{ hidden: { opacity: 0 }, shown: { opacity: [0.9, 0], scale: [1, 3.2], transition: { duration: 2, ease: "easeOut", repeat: Infinity, delay: 0.3 } } }}
            />
            <motion.circle
              cx={hub.x}
              cy={hub.y}
              r={0.9}
              fill="#f5a524"
              stroke="#0b1b3f"
              strokeWidth={1.5}
              vectorEffect="non-scaling-stroke"
              variants={{ hidden: { opacity: 0, scale: 0 }, shown: { opacity: 1, scale: 1, transition: { type: "spring", stiffness: 300, damping: 16, delay: 0.1 } } }}
            />
          </svg>

          {/* label as HTML so the text stays crisp at every size */}
          <motion.span
            // sits to the left of the hub so it doesn't cover the routes going south and east
            className="absolute -translate-x-full -translate-y-1/2 rounded-full bg-amber px-2.5 py-1 text-[11px] font-bold whitespace-nowrap text-navy shadow-[0_6px_16px_rgba(245,165,36,0.35)] lg:px-3.5 lg:py-1.5 lg:text-sm"
            style={{ left: `calc(${(hub.x / W) * 100}% - 14px)`, top: `${(hub.y / H) * 100}%` }}
            variants={{ hidden: { opacity: 0, x: 6 }, shown: { opacity: 1, x: 0, transition: { duration: 0.5, ease, delay: 0.25 } } }}
          >
            {hub.name}
          </motion.span>
        </motion.div>
      </div>
    </section>
  );
}
